import { ActionDefinition } from '../../../Action'
import { TableNameColumn, ChoiceColumn, DocumentIdColumn, StringColumn, TemplateValueColumn } from '../../../../db'

export const createOrUpdateRecord = ActionDefinition({
    $id: 'ab575ae253b3230034c6ddeeff7b12f1',
    name: 'Create or Update Record',
    description:
        'Create or update a record in a ServiceNow table by determining if it already exists. Add records that do not exist, and update existing ones. Identify existing records by selecting unique fields. Set field values dynamically and enforce server-side validation rules (data policy, business rules, dictionary-defined mandatory fields). UI policy does not apply.',
    inputs: {
        fields: TemplateValueColumn({
            label: 'Fields',
            mandatory: true,
            maxLength: 65000,
            dependent: 'table_name',
        }),
        table_name: TableNameColumn({
            label: 'Table Name',
            mandatory: true,
        }),
    },
    outputs: {
        status: ChoiceColumn({
            label: 'Status',
            maxLength: 8000,
            choices: {
                created: {
                    label: 'Created',
                    sequence: 1,
                },
                updated: {
                    label: 'Updated',
                    sequence: 2,
                },
                error: {
                    label: 'Error',
                    sequence: 3,
                },
            },
        }),
        record: DocumentIdColumn({
            label: 'Record',
            dependent: 'table_name',
        }),
        error_message: StringColumn({
            label: 'Error Message',
            maxLength: 8000,
        }),
        table_name: TableNameColumn({
            label: 'Table Name',
        }),
    },
})
